VALUES
  ('newtworks_v2_personality', 389, 'It is important for me to perform better than others on a task.', NULL, NULL, false, NULL, 'competitiveness', false, 'Helmreich & Spence 1978, WOFO (Work and Family Orientation Questionnaire), competitiveness factor, 5-item version. Popularized in sales context by Brown, Cron & Slocum 1998, Journal of Marketing 62(4) 88-98. Transcribed from a published reproduction attributed directly to Robert Helmreich (source: The Globe and Mail, "Too competitive? Careful it doesn''t bite you," citing Helmreich by name); wording cross-checked against Triandis INDCOL embedded WOFO items and secondary academic citations (Yearick 2018 dissertation; Frontiers 2018).', 5, 2, true),
  ('newtworks_v2_personality', 390, 'I feel that winning is important in both work and games.', NULL, NULL, false, NULL, 'competitiveness', false, 'Helmreich & Spence 1978, WOFO, competitiveness factor, 5-item version. Popularized in sales context by Brown, Cron & Slocum 1998, Journal of Marketing 62(4) 88-98. Transcribed from a published reproduction attributed directly to Robert Helmreich (The Globe and Mail, "Too competitive? Careful it doesn''t bite you").', 5, 2, true),
  ('newtworks_v2_personality', 391, 'It annoys me when people perform better than I do.', NULL, NULL, false, NULL, 'competitiveness', false, 'Helmreich & Spence 1978, WOFO, competitiveness factor, 5-item version. Popularized in sales context by Brown, Cron & Slocum 1998, Journal of Marketing 62(4) 88-98. Transcribed from a published reproduction attributed directly to Robert Helmreich (The Globe and Mail); wording confirmed against Triandis INDCOL embedded WOFO item ("It annoys me when other people perform better than I do").', 5, 2, true),
  ('newtworks_v2_personality', 392, 'I try harder when I''m in competition with others.', NULL, NULL, false, NULL, 'competitiveness', false, 'Helmreich & Spence 1978, WOFO, competitiveness factor, 5-item version. Popularized in sales context by Brown, Cron & Slocum 1998, Journal of Marketing 62(4) 88-98. Transcribed from a published reproduction attributed directly to Robert Helmreich (The Globe and Mail).', 5, 2, true),
  ('newtworks_v2_personality', 393, 'I enjoy working in situations when I''m in competition with others.', NULL, NULL, false, NULL, 'competitiveness', false, 'Helmreich & Spence 1978, WOFO, competitiveness factor, 5-item version. Popularized in sales context by Brown, Cron & Slocum 1998, Journal of Marketing 62(4) 88-98. Transcribed from a published reproduction attributed directly to Robert Helmreich (The Globe and Mail); wording confirmed against Triandis INDCOL embedded WOFO item ("I enjoy working in situations involving competition with others") and Frontiers 2018 citation of the Spence & Helmreich 1983 competitiveness subscale.', 5, 2, true);
